// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Easing, interpolate } from '../remotionShim';
// Single inline Zod Schema defining all user-customizable parameters


const items = [
  { label: "1-5", height: 160 },
  { label: "5-10", height: 280 },
  { label: "10-16", height: 420 },
  { label: "16-32", height: 500 },
  { label: "32-42", height: 380 },
  { label: "42-60", height: 240 },
  { label: "60+", height: 120 },
];

export type BouncingBallChartProps = Partial<z.infer<typeof BouncingBallChartSchema>>;

const BouncingBallChart: React.FC<BouncingBallChartProps> = ({
  backgroundColor = "#050507",
  transparentBackground = false,
  durationInSeconds = 6,
  ballColor = "#ffffff",
  ballSize = 28,
  barBorderColor = "#ffffff",
  textColor = "#8c8c9e",
  glowColor = "#ffffff",
  trailLength = 8,
  bounceHeight = 160,
  barHeightMultiplier = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Chart Dimensions & Setup
  const chartWidth = width * 0.75;
  const leftMargin = (width - chartWidth) / 2;
  const N = items.length;
  const M = N + 1; // Total bouncing segments (starts off-screen left, ends off-screen right)
  const spacing = chartWidth / (N - 1);
  const barWidth = Math.min(80, spacing * 0.55);
  const chartBaseY = height * 0.72; // Baseline Y coordinate for bottom of the bars

  // Frame Timing Configurations
  const startBounceFrame = 40; // Allow bars to animate up first
  const endBufferFrame = 15;
  const totalFrames = durationInSeconds * 30;
  const bounceDuration = Math.max(30, totalFrames - startBounceFrame - endBufferFrame);
  const framesPerSegment = bounceDuration / M;

  // Helper to get X position for a given bar index (including virtual start/end bars)
  const getX = (index: number) => {
    if (index === -1) return -ballSize * 2;
    if (index === N) return width + ballSize * 2;
    return leftMargin + index * spacing;
  };

  // Helper to get Y height for a given bar index
  const getY = (index: number) => {
    if (index === -1) return height * 0.7; // Start high in the air
    if (index === N) return -height * 0.5; // Bounce off the screen bottom-right
    return items[index] ? items[index].height * barHeightMultiplier : 0;
  };

  // Deterministic physics calculations for any frame
  const getBallState = (f: number) => {
    const bounceFrame = Math.max(0, f - startBounceFrame);
    const clampedBounceFrame = Math.min(bounceDuration, bounceFrame);

    // Segment & timeline calculations
    const segmentIndex = Math.floor(clampedBounceFrame / framesPerSegment);
    const currentSegment = Math.min(M - 1, segmentIndex);
    const t_segment = clampedBounceFrame - currentSegment * framesPerSegment;
    const u = Math.min(1, Math.max(0, t_segment / framesPerSegment));

    // 1. Horizontal Motion (Pure Constant Velocity)
    const x_start = getX(currentSegment - 1);
    const x_end = getX(currentSegment);
    const x = x_start + (x_end - x_start) * u;

    // 2. Vertical Motion (Newtonian Parabolic Arc under Uniform Gravity)
    const H_start = getY(currentSegment - 1);
    const H_end = getY(currentSegment);
    const H_peak = Math.max(H_start, H_end) + bounceHeight;

    // Boundary protections to prevent division by zero or square root of negative numbers
    const D1 = Math.max(0.1, H_peak - H_start);
    const D1_minus_D2 = Math.max(0.1, H_peak - H_end);
    const D2 = H_end - H_start;

    const A_coeff = -(2 * D1 - D2) - 2 * Math.sqrt(D1 * D1_minus_D2);
    const B_coeff = D2 - A_coeff;
    const C_coeff = H_start;

    const y = A_coeff * u * u + B_coeff * u + C_coeff;

    // 3. Motion Derivatives for Organic Squash & Stretch
    const dx_du = x_end - x_start;
    const dy_du = 2 * A_coeff * u + B_coeff;
    const speed = Math.sqrt(dx_du * dx_du + dy_du * dy_du);
    const angleCSS = Math.atan2(-dy_du, dx_du);

    // 4. Elastic Compression on Impact
    let scaleX = 1;
    let scaleY = 1;
    let isSquashing = false;
    let squashProgress = 0;

    // Check distance to the closest real bar's impact point
    for (let j = 0; j < N; j++) {
      const targetFrame = startBounceFrame + (j + 1) * framesPerSegment;
      const diff = Math.abs(f - targetFrame);
      if (diff <= 5) {
        isSquashing = true;
        squashProgress = 1 - diff / 5;
        scaleY = 1 - 0.35 * squashProgress; // Compress vertically
        scaleX = 1 + 0.3 * squashProgress;  // Expand horizontally to preserve mass
        break;
      }
    }

    // 5. Kinetic Stretching along velocity vector when in mid-air
    let rotation = 0;
    if (!isSquashing && clampedBounceFrame > 0 && clampedBounceFrame < bounceDuration) {
      const stretchAmount = Math.min(0.22, (speed / spacing) * 0.05);
      scaleX = 1 + stretchAmount;
      scaleY = 1 - stretchAmount;
      rotation = angleCSS;
    }

    return {
      x,
      y,
      scaleX,
      scaleY,
      rotation,
      currentSegment,
    };
  };

  // Current active state
  const ballState = getBallState(frame);
  const ballEntranceScale = interpolate(frame, [15, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.back(1.5)),
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif",
        color: textColor,
        overflow: "hidden",
      }}
    >
      {/* Decorative Grid Lines */}
      {[150, 300, 450].map((h, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            left: leftMargin - 100,
            width: chartWidth + 200,
            top: chartBaseY - h,
            height: 1,
            borderTop: `1px dashed rgba(255, 255, 255, 0.04)`,
            pointerEvents: "none",
            transition: "none",
          }}
        />
      ))}

      {/* Bar Chart Container */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: 0,
          bottom: 0,
          pointerEvents: "none",
        }}
      >
        {items.map((item, index) => {
          const currentHeight = item.height * barHeightMultiplier;

          // Staggered entry animation for the bars
          const barHeightScale = interpolate(frame, [index * 3, index * 3 + 20], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.quad),
          });

          // Proximity calculation for dynamic light emission on bar impact
          const barX = getX(index);
          const barY = currentHeight;
          const dx = ballState.x - barX;
          const dy = ballState.y - barY;
          const distance = Math.sqrt(dx * dx + dy * dy);
          const barGlowIntensity = Math.max(0, 1 - distance / 110);

          // Highlight progress for labels sitting directly below
          const labelHighlight = Math.max(0, 1 - Math.abs(ballState.x - barX) / (spacing * 0.95));

          return (
            <React.Fragment key={index}>
              {/* Hollow Rectangular Bar */}
              <div
                style={{
                  position: "absolute",
                  left: barX - barWidth / 2,
                  top: chartBaseY - currentHeight * barHeightScale,
                  width: barWidth,
                  height: currentHeight * barHeightScale,
                  border: `2px solid ${barBorderColor}`,
                  borderRadius: "4px 4px 0 0",
                  boxSizing: "border-box",
                  backgroundColor: "transparent",
                  opacity: 0.85,
                  transition: "none",
                  boxShadow:
                    barGlowIntensity > 0
                      ? `0 0 ${barGlowIntensity * 25}px rgba(255,255,255,0.2), inset 0 0 ${
                          barGlowIntensity * 15
                        }px rgba(255,255,255,0.15)`
                      : "none",
                }}
              />

              {/* Glowing Impact Contact Line */}
              {barGlowIntensity > 0 && barHeightScale === 1 && (
                <div
                  style={{
                    position: "absolute",
                    left: barX - barWidth / 2 - 4,
                    top: chartBaseY - barY - 2,
                    width: barWidth + 8,
                    height: 4,
                    borderRadius: 2,
                    backgroundColor: glowColor,
                    boxShadow: `0 0 ${barGlowIntensity * 16}px ${glowColor}, 0 0 ${
                      barGlowIntensity * 32
                    }px ${glowColor}`,
                    opacity: barGlowIntensity,
                    transition: "none",
                  }}
                />
              )}

              {/* Responsive Metric Category Labels */}
              <div
                style={{
                  position: "absolute",
                  left: barX - spacing / 2,
                  top: chartBaseY + 24,
                  width: spacing,
                  textAlign: "center",
                  color: labelHighlight > 0.5 ? "#ffffff" : textColor,
                  fontSize: 18,
                  fontWeight: 600,
                  transform: `scale(${1 + 0.12 * labelHighlight})`,
                  opacity: 0.5 + 0.5 * labelHighlight,
                  transition: "none",
                }}
              >
                {item.label}
              </div>
            </React.Fragment>
          );
        })}
      </div>

      {/* Render Trail Behind the Ball */}
      {trailLength > 0 &&
        Array.from({ length: trailLength }).map((_, i) => {
          const trailFrame = frame - (i + 1) * 1.4;
          if (trailFrame < startBounceFrame) return null;

          const tState = getBallState(trailFrame);
          const trailOpacity = (1 - (i + 1) / (trailLength + 1)) * 0.35 * ballEntranceScale;
          const trailSize = ballSize * (1 - ((i + 1) / (trailLength + 1)) * 0.3);

          // Correct vertical centering to match physics simulation
          const center_CSS_Y = chartBaseY - tState.y - (trailSize * tState.scaleY) / 2;
          const trailTop = center_CSS_Y - trailSize / 2;

          return (
            <div
              key={`trail-${i}`}
              style={{
                position: "absolute",
                left: tState.x - trailSize / 2,
                top: trailTop,
                width: trailSize,
                height: trailSize,
                borderRadius: "50%",
                backgroundColor: ballColor,
                opacity: trailOpacity,
                pointerEvents: "none",
                transform: `rotate(${tState.rotation}rad) scale(${tState.scaleX}, ${tState.scaleY})`,
                filter: `blur(${1 + i * 0.3}px) drop-shadow(0 0 10px ${glowColor})`,
                transition: "none",
              }}
            />
          );
        })}

      {/* The Active Physic-Simulated Ball */}
      <div
        style={{
          position: "absolute",
          left: ballState.x - ballSize / 2,
          top: chartBaseY - ballState.y - (ballSize * ballState.scaleY) / 2 - ballSize / 2,
          width: ballSize,
          height: ballSize,
          borderRadius: "50%",
          backgroundColor: ballColor,
          transform: `rotate(${ballState.rotation}rad) scale(${ballState.scaleX}, ${ballState.scaleY})`,
          transformOrigin: "center center",
          opacity: ballEntranceScale,
          boxShadow: `0 0 20px ${glowColor}, 0 0 40px rgba(255, 255, 255, 0.4)`,
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default BouncingBallChart;